<script setup lang="ts">
const route=useRoute(),member=useMember(),id=ref(''),ready=ref(false),error=ref(''),busy=ref(false);
onMounted(async()=>{id.value=typeof route.query.id==='string'?route.query.id:'';if(!/^[a-f0-9-]{36}$/.test(id.value)){error.value='Invalid native sign-in request.';return;}try{const pre=(await $fetch<{data:{csrfToken:string}}>('/api/v1/auth/preflight')).data;await $fetch('/api/v1/auth/native/bind',{method:'POST',body:{id:id.value},headers:{'X-CSRF-Token':pre.csrfToken}});localStorage.setItem('aggregator-native-pending',JSON.stringify({id:id.value,expires:Date.now()+900000}));await member.refresh();ready.value=true;}catch{error.value='This request has expired, belongs to another browser or is unavailable. Start again in the app.';}});
async function approve(){busy.value=true;try{const result=await member.mutate<{data:{callback:string}}>('/api/v1/auth/native/approve','POST',{id:id.value});const url=new URL(result.data.callback);if(url.protocol!=='aggregator-local:'||url.hostname!=='auth'||url.pathname!=='/callback')throw Error('Invalid callback');localStorage.removeItem('aggregator-native-pending');location.assign(result.data.callback);}catch{error.value='Approval could not be completed. Return to the app and start a new request.';}finally{busy.value=false;}}
function cancel(){localStorage.removeItem('aggregator-native-pending');void navigateTo('/');}
useHead({title:'Connect the native reader — The Aggregator',meta:[{name:'referrer',content:'no-referrer'}]});
</script>
<template><MemberFrame><h1>Connect your native reader</h1><p>This local Android app will access your own saved stories, interests and listening settings. It receives reader access only, with local captured-mail assurance.</p><template v-if="ready"><template v-if="member.session.value"><p>Continue as <strong>{{ member.session.value.user.displayName }}</strong>?</p><ControlButton label="Approve native reader" :disabled="busy" @click="approve"/></template><template v-else><p>First sign in in this browser. Then return here to approve the connection explicitly.</p><NuxtLink to="/sign-in">Sign in or create an account</NuxtLink> · <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">Open local captured mailbox</a></template></template><ControlButton label="Cancel connection" @click="cancel"/><p role="alert">{{ error }}</p></MemberFrame></template>
